int note = 14;

if (note >= 10) {
    System.out.println("Admis");
} else if (note >= 8) {
    System.out.println("Rattrapage");
} else {
    System.out.println("Refusé");
}

// Switch expression (Java 14+)
String mention = switch (note / 5) {
    case 4 -> "Très bien";
    case 3 -> "Bien";
    default -> "Passable";
};

// Ternaire
String resultat = (note >= 10) ? "Admis" : "Refusé";
